return $input.all().map((item) => {
  const customer = item.json;
  const budget = Number(customer.budget ?? 0);

  let category = 'LOW_VALUE';

  if (budget >= 100000) {
    category = 'HIGH_VALUE';
  } else if (budget >= 25000) {
    category = 'MEDIUM_VALUE';
  }

  return {
    json: {
      ...customer,
      category,
      processedAt: new Date().toISOString()
    }
  };
});

const processed = $input.all();

const summary = {
  totalProcessed: processed.length,
  highValue: processed.filter(i => i.json.category === 'HIGH_VALUE').length,
  mediumValue: processed.filter(i => i.json.category === 'MEDIUM_VALUE').length,
  lowValue: processed.filter(i => i.json.category === 'LOW_VALUE').length,
  completedAt: new Date().toISOString()
};

return [
  {
    json: {
      success: true,
      message: 'Batch processing completed',
      summary,
      customers: processed.map(i => i.json)
    }
  }
];
